using BandUp.Application.Abstractions;

namespace BandUp.Application.Features.Exams.SubmitAttempt;

/// <summary>
/// The final submission. <see cref="IdempotencyKey"/> is generated by the client once per
/// submit click and resent unchanged on every retry. <see cref="Answers"/> are the answers still
/// unsaved at the moment of submitting; the ones already autosaved need not be repeated.
/// </summary>
public sealed record SubmitAttemptCommand(
    Guid AttemptId,
    string IdempotencyKey,
    IReadOnlyList<SubmittedAnswerInput> Answers)
    : ICommand<AttemptResultDto>;

public sealed record SubmittedAnswerInput(Guid QuestionId, string? SelectedAnswer);
